//! Schemas generated by `schemars` compile and validate as expected.
#![cfg(feature = "schemars")]

use rune_chain_output_parser::{Extractor, StructuredError, schema_for};
use schemars::JsonSchema;
use serde::Deserialize;

#[derive(Debug, Deserialize, JsonSchema, PartialEq)]
#[serde(rename_all = "snake_case")]
enum Severity {
    Low,
    High,
}

#[derive(Debug, Deserialize, JsonSchema, PartialEq)]
struct Location {
    file: String,
    line: u32,
}

#[derive(Debug, Deserialize, JsonSchema, PartialEq)]
struct Finding {
    severity: Severity,
    note: Option<String>,
    locations: Vec<Location>,
}

#[test]
fn derived_schema_round_trips() {
    let ex = Extractor::<Finding>::for_type().unwrap();
    assert_eq!(ex.name(), "Finding");
    let f = ex
        .parse(r#"Result: {"severity": "high", "note": null, "locations": [{"file": "a.rs", "line": 3}]}"#)
        .unwrap();
    assert_eq!(f.severity, Severity::High);
    assert_eq!(f.locations[0].line, 3);
}

#[test]
fn derived_schema_rejects_bad_values() {
    let ex = Extractor::<Finding>::for_type().unwrap();
    for bad in [
        r#"{"severity": "critical", "note": null, "locations": []}"#,
        r#"{"severity": "low", "note": 1, "locations": []}"#,
        r#"{"severity": "low", "note": null, "locations": [{"file": "a", "line": -1}]}"#,
        r#"{"severity": "low", "note": null}"#,
    ] {
        assert!(
            matches!(ex.parse(bad), Err(StructuredError::SchemaViolation(_))),
            "{bad}"
        );
    }
}

#[test]
fn schema_uses_defs() {
    let schema = schema_for::<Finding>();
    assert!(schema.get("$defs").is_some(), "{schema}");
}
